# Face -> table. Obliques share the upright widths (true of the AFMs); Arial
# and Times New Roman are metric-compatible with Helvetica and Times.
_ALIASES = {
    "Helvetica": "Helvetica", "Helvetica-Oblique": "Helvetica",
    "Helvetica-Bold": "Helvetica-Bold", "Helvetica-BoldOblique": "Helvetica-Bold",
    "Times-Roman": "Times-Roman", "Times-Bold": "Times-Bold",
    "Times-Italic": "Times-Italic", "Times-BoldItalic": "Times-BoldItalic",
    "Arial": "Helvetica", "ArialMT": "Helvetica", "Arial-ItalicMT": "Helvetica", "Arial,Italic": "Helvetica",
    "Arial-BoldMT": "Helvetica-Bold", "Arial,Bold": "Helvetica-Bold",
    "Arial-BoldItalicMT": "Helvetica-Bold", "Arial,BoldItalic": "Helvetica-Bold",
    "TimesNewRoman": "Times-Roman", "TimesNewRomanPSMT": "Times-Roman",
    "TimesNewRoman,Bold": "Times-Bold", "TimesNewRomanPS-BoldMT": "Times-Bold",
    "TimesNewRoman,Italic": "Times-Italic", "TimesNewRomanPS-ItalicMT": "Times-Italic",
    "TimesNewRoman,BoldItalic": "Times-BoldItalic", "TimesNewRomanPS-BoldItalicMT": "Times-BoldItalic",
}
_MONOSPACE = {"Courier", "Courier-Bold", "Courier-Oblique", "Courier-BoldOblique",
              "CourierNew", "CourierNewPSMT", "CourierNew,Bold", "CourierNewPS-BoldMT"}
_TABLES: Dict[str, Dict[str, int]] = {}


def core14_widths(base_font: str) -> Optional[Dict[str, int]]:
    """``{character: width}`` for a standard-14 face (subset tag ignored), or None."""
    name = str(base_font or "").lstrip("/")
    name = name.split("+", 1)[1] if "+" in name[:7] else name
    if name in _MONOSPACE:
        return {ch: 600 for ch in _ALPHABET}
    key = _ALIASES.get(name)
    if key is None:
        return None
    if key not in _TABLES:
        _TABLES[key] = dict(zip(_ALPHABET, _WIDTHS[key]))
    return _TABLES[key]


__all__ = ["core14_widths"]
